<script lang="ts">
 import {onMount} from 'svelte';
 import {checkPluginRun,createPilotReach,createPluginRunGrant,pluginPostJson,skipWhileBusy,startPluginRun,type GlobalWindowProps,type JsonValue,type PluginRunPolicy,type ServerBot} from '../../../web/src/plugin-api/index.ts';
 import {createTrainingAccountPass} from '../training/accountPass.ts';
 import {prepareHeldPilot} from '../heldPilot.ts';
 import type {FoundAgent} from '../shared/types.ts';
 import {validateFleetSelection} from './fleetSelection.ts';
 let {sessions=[]}:GlobalWindowProps=$props();
 type Pilot={characterID:number;name:string;accountName:string};
 type Inspection={characterID:number;shipID:number;stationID:number;systemID:number;observedAt:number};
 type Review={setup:JsonValue;fingerprint:string;pilots:Pilot[];policies:PluginRunPolicy[]};
 let account=$state(''),pilots=$state<Pilot[]>([]),chosen=$state<number[]>([]),ownerID=$state(0),agentID=$state<number|null>(null),count=$state(1),agentMode=$state<'manual'|'auto'>('manual'),maxJumps=$state(10),corporationID=$state(''),durationMinutes=$state(720),parkingMode=$state<'nearest'|'selected'>('nearest'),parkingKind=$state<'station'|'structure'>('station'),parkingDestinationID=$state<number|null>(null),parkingSystemID=$state<number|null>(null),query=$state(''),agents=$state<FoundAgent[]>([]),capped=$state(false),busy=$state(false),message=$state(''),rosterError=$state(''),bots=$state<readonly ServerBot[]>([]),reviewed=$state<Review|null>(null);
 const selection=$derived(chosen.map(id=>pilots.find(p=>p.characterID===id)).filter((p):p is Pilot=>!!p));
 const fingerprint=$derived(JSON.stringify([chosen,ownerID,agentID,agentMode,maxJumps,corporationID,count,durationMinutes,parkingMode,parkingKind,parkingDestinationID,parkingSystemID,selection.map(p=>[p.characterID,p.accountName])]));
 const valid=$derived(!!reviewed&&reviewed.fingerprint===fingerprint);
 const matching=$derived(agents.filter(a=>[a.name,a.stationName,a.solarSystemName,a.corporationName].some(v=>v?.toLowerCase().includes(query.trim().toLowerCase()))));
 const fleetBots=$derived(bots.filter(b=>b.kind==='plugin'&&b.plugin?.pluginID==='uoc'&&['security-fleet-owner','security-fleet-assistant'].includes(b.plugin.run)));
 const reach=createPilotReach({pass:createTrainingAccountPass(),held:()=>sessions,known:()=>pilots.map(p=>({characterID:p.characterID,characterName:p.name,accountName:p.accountName})),accounts:()=>[...new Set(pilots.map(p=>p.accountName))]});
 const clear=()=>{reviewed=null;message='';};
 async function refresh(){try{const r=await reach.readServerBots();rosterError=r.allFailed?'Could not read Security fleet runs.':r.missing.length?`Could not read runs for ${r.missing.join(', ')}.`:'';if(!r.allFailed)bots=r.bots;}catch(e){rosterError=e instanceof Error?e.message:String(e);}}
 async function load(){const name=account.trim();if(!name||busy)return;busy=true;clear();try{const options=await reach.accountOptions(name);if(!options.token)throw Error('Account authentication is unavailable.');const r=await(options.fetch??fetch)(`${options.baseUrl??''}/api/pilot-training/characters`,{headers:{authorization:`Bearer ${options.token}`},credentials:'omit'}),body=await r.json();if(!r.ok||body?.ok!==true||typeof body.account!=='string'||body.account.toLowerCase()!==name.toLowerCase()||account.trim()!==name||!Array.isArray(body.characters))throw Error('The current account roster is unavailable.');const rows:Pilot[]=body.characters.map((c:any)=>{if(!Number.isSafeInteger(c?.characterID)||c.characterID<=0||typeof c.name!=='string'||!c.name)throw Error('Account roster is malformed.');return {characterID:c.characterID,name:c.name,accountName:body.account};});if(new Set(rows.map(p=>p.characterID)).size!==rows.length)throw Error('Account roster contains duplicate pilots.');const removed=pilots.filter(p=>p.accountName.toLowerCase()===name.toLowerCase()).map(p=>p.characterID);chosen=chosen.filter(id=>!removed.includes(id));pilots=[...pilots.filter(p=>p.accountName.toLowerCase()!==name.toLowerCase()),...rows];message=`Loaded ${rows.length} pilot(s) from ${name}.`;}catch(e){message=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function find(){if(busy)return;busy=true;clear();try{const p=selection.find(p=>p.characterID===ownerID);if(!p)throw Error('Choose the mission owner.');const o=await reach.accountOptions(p.accountName),r=await(o.fetch??fetch)(`${o.baseUrl??''}/api/agents/find?kind=encounter&level=1&limit=5000`,{headers:o.token?{authorization:`Bearer ${o.token}`}:{},credentials:o.token?'omit':'same-origin'}),body=await r.json();if(!r.ok||body?.ok===false||!Array.isArray(body.agents)||typeof body.capped!=='boolean')throw Error('Security agent directory is unavailable.');agents=body.agents.filter((a:FoundAgent)=>a.agentID>0&&a.level===1&&a.divisionID===24&&a.agentTypeID===2&&a.stationID!==null);capped=body.capped;agentID=null;}catch(e){message=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function waitInspection(id:string,p:Pilot):Promise<Inspection>{const until=Date.now()+120000;while(Date.now()<until){const r=await reach.readServerBots();if(r.allFailed||r.missing.length)throw Error('Inspection status is unavailable; check the runs before retrying.');bots=r.bots;const b=r.bots.find(x=>x.botID===id&&x.characterID===p.characterID);if(b?.endedAt){if(b.phase!=='Fleet Security pilot inspected')throw Error(b.why??'Pilot inspection failed.');const x=b.plugin?.readout as unknown as Inspection;if(!x||x.characterID!==p.characterID||![x.shipID,x.stationID,x.systemID].every(n=>Number.isSafeInteger(n)&&n>0)||!Number.isFinite(x.observedAt))throw Error('Pilot inspection is incomplete.');return x;}await new Promise(resolve=>setTimeout(resolve,1000));}throw Error('Pilot inspection timed out; check the run before retrying.');}
 async function review(){if(busy)return;busy=true;clear();try{const list=[...selection],initial=fingerprint;validateFleetSelection(list,chosen,ownerID,agentID,count,agentMode==='auto');if(agentMode==='manual'&&!agents.some(a=>a.agentID===agentID))throw Error('Choose a Security agent from the current directory.');const inspected:Inspection[]=[];for(const p of list){message=`Inspecting ${p.name}…`;const held=sessions.find(s=>s.store.get().station.online?.characterID===p.characterID);if(held)await prepareHeldPilot(held,p.characterID);const options=await reach.accountOptions(p.accountName),check=await checkPluginRun('uoc','coc-fleet-inspect',{},options),run=await startPluginRun(p.characterID,'uoc','coc-fleet-inspect',check.setup,createPluginRunGrant(check.policy),options);inspected.push(await waitInspection(run.botID,p));if(initial!==fingerprint)throw Error('Selection changed during inspection.');}if(new Set(inspected.map(x=>x.shipID)).size!==list.length)throw Error('Each pilot must have a distinct ship.');if(!Number.isSafeInteger(durationMinutes)||durationMinutes<4||durationMinutes>4320)throw Error('Choose a runtime between 4 and 4320 minutes.');if(parkingMode==='selected'&&(!Number.isSafeInteger(parkingDestinationID)||!parkingDestinationID||parkingDestinationID<=0||!Number.isSafeInteger(parkingSystemID)||!parkingSystemID||parkingSystemID<=0))throw Error('Enter the destination and solar system IDs.');const corp=corporationID.trim()?Number(corporationID):null;if(agentMode==='auto'&&(!Number.isSafeInteger(maxJumps)||maxJumps<0||maxJumps>100||corp!==null&&(!Number.isSafeInteger(corp)||corp<=0)))throw Error('Enter a valid corporation and maximum jumps.');const setup={operationID:`coc-${crypto.randomUUID()}`,operationRunID:crypto.randomUUID(),missionOwnerID:ownerID,...(agentMode==='manual'?{agentID}:{agent:{mode:'auto',maxJumps,corporationID:corp}}),missionCount:count,...(parkingMode==='selected'?{parking:{mode:'selected',kind:parkingKind,destinationID:parkingDestinationID,systemID:parkingSystemID}}:{}),members:inspected.map(x=>({characterID:x.characterID,shipID:x.shipID}))};const policies:PluginRunPolicy[]=[];for(const p of list){const o=await reach.accountOptions(p.accountName),r=await checkPluginRun('uoc',p.characterID===ownerID?'security-fleet-owner':'security-fleet-assistant',setup as JsonValue,o);if(JSON.stringify(r.setup)!==JSON.stringify(setup))throw Error('The reviewed fleet setup changed.');policies.push(r.policy);}if(initial!==fingerprint)throw Error('Selection changed. Review again.');reviewed={setup:setup as JsonValue,fingerprint:initial,pilots:list,policies};message='Pilot ships inspected and fleet ready for review.';}catch(e){message=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function start(){if(busy||!reviewed||!valid)return;busy=true;message='';const approved=reviewed,started:{id:string;pilot:Pilot}[]=[];reviewed=null;try{for(let i=0;i<approved.pilots.length;i++){const p=approved.pilots[i]!,held=sessions.find(s=>s.store.get().station.online?.characterID===p.characterID);if(held)await prepareHeldPilot(held,p.characterID);if(fingerprint!==approved.fingerprint)throw Error('Fleet selection changed.');const o=await reach.accountOptions(p.accountName),b=await startPluginRun(p.characterID,'uoc',p.characterID===ownerID?'security-fleet-owner':'security-fleet-assistant',approved.setup,createPluginRunGrant(approved.policies[i]!,durationMinutes),o);started.push({id:b.botID,pilot:p});}message='Security fleet runs started.';await refresh();}catch(e){const first=started[0];if(first)try{await pluginPostJson('uoc',`/runs/${encodeURIComponent(first.id)}/stop`,{},await reach.accountOptions(first.pilot.accountName));}catch{/* retain uncertain custody */}message=`${e instanceof Error?e.message:String(e)} Check the run roster before retrying.`;await refresh();}finally{busy=false;}}
 async function stop(bot:ServerBot){busy=true;try{await pluginPostJson('uoc',`/runs/${encodeURIComponent(bot.botID)}/stop`,{},await reach.ownerOptions(bot.characterID));message='Security fleet stop requested.';await refresh();}catch(e){message=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 onMount(()=>{const tick=skipWhileBusy(refresh);void tick();const timer=setInterval(()=>void tick(),5000);return()=>{clearInterval(timer);void reach.release();};});
</script>
<section aria-label="Hosted Security fleet missions">
 <h3>Security missions · fleet level 1</h3><p>Two to eight pilots use drone combat in The Blockade or Alluring Emanations. The selected owner requests and completes each mission. Other offers remain unaccepted; fleet gate progression is not yet qualified.</p>
 <label>Fleet account <input bind:value={account} disabled={busy}/></label><button type="button" onclick={load} disabled={busy||!account.trim()}>Load fleet pilots</button>
 <fieldset disabled={busy}><legend>Fleet pilots</legend>{#each pilots as p (p.characterID)}<label><input type="checkbox" value={p.characterID} bind:group={chosen} onchange={clear}/>{p.name} · {p.accountName} ({p.characterID})</label>{/each}</fieldset>
 <label>Mission owner <select bind:value={ownerID} onchange={clear} disabled={busy}><option value={0}>Choose owner</option>{#each selection as p (p.characterID)}<option value={p.characterID}>{p.name} · {p.accountName}</option>{/each}</select></label>
 <label>Fleet agent selection <select bind:value={agentMode} onchange={clear} disabled={busy}><option value="manual">Choose an agent</option><option value="auto">Automatic eligible agent</option></select></label><label>Fleet missions <select bind:value={count} onchange={clear} disabled={busy}><option value={1}>1</option><option value={2}>2</option></select></label>{#if agentMode==='manual'}<button type="button" onclick={find} disabled={busy||!ownerID}>Find fleet Security agents</button>{:else}<label>Fleet maximum jumps <input type="number" min="0" max="100" bind:value={maxJumps} onchange={clear} disabled={busy}/></label><label>Fleet NPC corporation ID (optional) <input inputmode="numeric" bind:value={corporationID} onchange={clear} disabled={busy}/></label>{/if}
 {#if agentMode==='manual'&&agents.length}<label>Search fleet agent <input type="search" bind:value={query}/></label><label>Fleet agent <select bind:value={agentID} onchange={clear} disabled={busy}><option value={null}>Choose agent</option>{#each matching as a (a.agentID)}<option value={a.agentID}>{a.name} · {a.stationName??'Station unavailable'} · {a.corporationName??''}</option>{/each}</select></label>{/if}
 <label>Fleet runtime limit (minutes) <input type="number" min="4" max="4320" step="1" bind:value={durationMinutes} onchange={clear} disabled={busy}/></label><label>Fleet parking <select bind:value={parkingMode} onchange={clear} disabled={busy}><option value="nearest">Nearest accessible dock at stop</option><option value="selected">Selected destination</option></select></label>{#if parkingMode==='selected'}<label>Fleet destination type <select bind:value={parkingKind} onchange={clear} disabled={busy}><option value="station">NPC station</option><option value="structure">Accessible structure</option></select></label><label>Fleet destination ID <input type="number" min="1" bind:value={parkingDestinationID} onchange={clear} disabled={busy}/></label><label>Fleet solar system ID <input type="number" min="1" bind:value={parkingSystemID} onchange={clear} disabled={busy}/></label>{/if}
 {#if capped}<p>Only part of the agent directory was returned.</p>{/if}<button type="button" onclick={review} disabled={busy||(agentMode==='manual'&&!agentID)}>Inspect and review Security fleet</button>
 {#if reviewed&&valid}<div aria-label="Security fleet review"><p>Mission owner: {selection.find(p=>p.characterID===ownerID)?.name}; pilots: {reviewed.pilots.map(p=>p.name).join(', ')}; missions: {count}; agent: {agentMode==='auto'?`automatic within ${maxJumps} jumps`:'selected'}; runtime limit: {durationMinutes} minutes; parking: {parkingMode==='nearest'?'nearest accessible dock':`selected ${parkingKind} ${parkingDestinationID} in system ${parkingSystemID}`}.</p><p>Each pilot's current ship was inspected. Risks: {reviewed.policies.map(p=>p.riskClasses.join(', ')||'none').join('; ')}.</p><button type="button" onclick={start} disabled={busy}>Approve and start Security fleet</button></div>{/if}
 {#if message}<p role="status">{message}</p>{/if}<h4>Security fleet runs</h4><button type="button" onclick={refresh} disabled={busy}>Refresh Security fleet</button>{#if rosterError}<p role="alert">{rosterError}</p>{/if}{#each fleetBots as bot (bot.botID)}<div><p>{bot.characterName??'Pilot'} · {bot.phase??bot.status}{bot.endedAt?' · ended':''}</p>{#if bot.why}<p>{bot.why}</p>{/if}{#if !bot.endedAt}<button type="button" onclick={()=>stop(bot)} disabled={busy}>Stop Security fleet</button>{/if}</div>{/each}
</section>
<style>label{display:grid;gap:.25rem;margin-block:.5rem}fieldset label{display:block}</style>
